const body = $input.all()[0].json.body || {};
const action = body.action || 'ping';

let response = {
  success: true,
  action: action,
  timestamp: new Date().toISOString()
};

if (action === 'create_exam') {
  const total = Number(body.totalMarks) || 100;
  const passing = Number(body.passingMarks) || 40;
  const obtained = (body.marksObtained !== undefined && body.marksObtained !== '' && body.marksObtained !== null) 
    ? Number(body.marksObtained) : null;

  let grade = null;
  let percentage = null;
  let passed = null;

  if (obtained !== null) {
    percentage = Math.round((obtained / total) * 100 * 10) / 10;
    passed = obtained >= passing;
    if (percentage >= 90) grade = 'A+';
    else if (percentage >= 80) grade = 'A';
    else if (percentage >= 70) grade = 'B';
    else if (percentage >= 60) grade = 'C';
    else if (percentage >= 50) grade = 'D';
    else grade = 'F';
  }

  const exam = {
    id: body.id || ('EX-' + Math.floor(1000 + Math.random() * 9000)),
    studentId: body.studentId || 'STU-001',
    studentName: body.studentName || 'Student Name',
    subject: body.subject || 'General Studies',
    examTitle: body.examTitle || 'Midterm Assessment',
    examDate: body.examDate || new Date().toISOString().split('T')[0],
    totalMarks: total,
    passingMarks: passing,
    marksObtained: obtained,
    percentage: percentage,
    grade: grade,
    passed: passed,
    status: obtained !== null ? 'Graded' : (body.status || 'Scheduled'),
    feedback: body.feedback || (obtained !== null ? (passed ? 'Cleared successfully' : 'Needs improvement') : 'Pending exam date')
  };

  response.data = exam;
  response.message = 'Exam scheduled/recorded successfully in n8n';
} else if (action === 'record_score') {
  const total = Number(body.totalMarks) || 100;
  const passing = Number(body.passingMarks) || 40;
  const obtained = Number(body.marksObtained) || 0;
  const percentage = Math.round((obtained / total) * 100 * 10) / 10;
  const passed = obtained >= passing;

  let grade = 'F';
  if (percentage >= 90) grade = 'A+';
  else if (percentage >= 80) grade = 'A';
  else if (percentage >= 70) grade = 'B';
  else if (percentage >= 60) grade = 'C';
  else if (percentage >= 50) grade = 'D';

  response.data = {
    id: body.id,
    studentId: body.studentId,
    marksObtained: obtained,
    totalMarks: total,
    percentage: percentage,
    grade: grade,
    passed: passed,
    status: 'Graded',
    feedback: body.feedback || (passed ? 'Passed with satisfactory performance' : 'Remedial assessment suggested'),
    updatedAt: new Date().toISOString()
  };
  response.message = 'Score calculated and grade assigned by n8n workflow';
} else if (action === 'get_summary') {
  response.data = {
    status: 'online',
    workflowName: 'Student Exam Management CRM Pipeline',
    version: '1.0.0',
    capabilities: ['create_exam', 'record_score', 'bulk_sync', 'analytics']
  };
  response.message = 'Workflow connection active and operational';
} else {
  response.message = 'Action ' + action + ' received and processed successfully';
  response.data = body;
}

return [{ json: { response } }];
